  const how = { 1: 'И1', 2: 'И2, И3', 3: 'И2, И3', 4: 'И4', 5: '—', 6: 'И4, И5, И6', 7: '—', 8: 'И6, И7, И8', 9: 'И5, И9', 10: 'И10' };
  x.push(H1('12. Сравнение текущей и новой моделей процесса', { pageBreak: false }));
