  x.push(H2('12.4. Условия и риски внедрения'));
  x.push(bullet(`Поставщики должны согласиться на рамочный контракт и оплату остатка против копии коносамента. Для тех, кто не согласится, этап 6 останется прежним, и цикл по их поставкам сократится примерно на ${fmt(T.noBlCut)} дня вместо ${fmt(T.cut)}.`));
