function pageNumberFooter() {
  return new Footer({ children: [new Paragraph({ alignment: AlignmentType.CENTER, children: [new TextRun({ children: [PageNumber.CURRENT], size: PT(12), font: FONT })] })] });
}
function build(pages) {
  const portrait = (children, extra = {}) => ({
    properties: { page: { size: PORTRAIT, margin: MARGIN_P }, ...extra },
    footers: { default: pageNumberFooter() }, children,
  });
  const landscape = (children) => ({
    properties: { page: { size: { ...PORTRAIT, orientation: PageOrientation.LANDSCAPE }, margin: MARGIN_L } },
    footers: { default: pageNumberFooter() }, children,
  });
  listInstance = 0;
  return new Document({
    creator: 'Багишев Алихан Ахадович',
    title: 'Моделирование и анализ бизнес-процесса импортной закупки товара',
    description: 'Аналитическая работа, контрольная точка № 1',
    styles: {
      default: { document: { run: { font: FONT, size: PT(14) }, paragraph: { spacing: { line: 360, lineRule: LineRuleType.AUTO } } } },
      paragraphStyles: [
        { id: 'Heading1', name: 'Heading 1', basedOn: 'Normal', next: 'Normal', quickFormat: true, run: { font: FONT, size: PT(14), bold: true, color: '000000' }, paragraph: { outlineLevel: 0, keepNext: true } },
        { id: 'Heading2', name: 'Heading 2', basedOn: 'Normal', next: 'Normal', quickFormat: true, run: { font: FONT, size: PT(14), bold: true, color: '000000' }, paragraph: { outlineLevel: 1, keepNext: true } },
      ],
    },
    numbering: {
      config: [
        { reference: 'dash', levels: [{ level: 0, format: LevelFormat.BULLET, text: '–', alignment: AlignmentType.LEFT, style: { paragraph: { indent: { left: INDENT + 360, hanging: 360 } } } }] },
        { reference: 'src', levels: [{ level: 0, format: LevelFormat.DECIMAL, text: '%1.', alignment: AlignmentType.LEFT, style: { paragraph: { indent: { left: 567, hanging: 567 } } } }] },
        { reference: 'num', levels: [{ level: 0, format: LevelFormat.DECIMAL, text: '%1)', alignment: AlignmentType.LEFT, style: { paragraph: { indent: { left: INDENT + 400, hanging: 400 } } } }] },
      ],
    },
    sections: [
      portrait([...titlePage(), ...tocBlock(pages), ...body()], { titlePage: true }),
      landscape(asisFigures()),
      portrait([...problems(), ...tobeText()]),
      landscape(tobeFigures()),
      portrait([...compare(), ...ending()]),
    ],
  });
}

