const tmp = join(here, 'build', 'pass');
mkdirSync(tmp, { recursive: true });
const soffice = '/root/.claude/skills/synced/504691b4-9f2b-49f2-a95f-144d515b514d_142bcb9c-ce61-4762-ac41-0b0068b2e775/docx/scripts/office/soffice.py';
function toPdf(docxPath) {
  execSync(`python3 "${soffice}" --headless --convert-to pdf --outdir "${tmp}" "${docxPath}"`, { stdio: 'pipe' });
  return docxPath.replace(/\.docx$/, '.pdf').replace(dirname(docxPath), tmp);
}
function findPages(pdf) {
  const n = Number(execSync(`pdfinfo "${pdf}"`).toString().match(/Pages:\s+(\d+)/)[1]);
  const norm = (s) => s.replace(/\s+/g, ' ').trim();
  const texts = [];
  for (let i = 1; i <= n; i++) texts.push(norm(execSync(`pdftotext -f ${i} -l ${i} -layout "${pdf}" -`).toString()));
  const pages = {};
  for (const [title, probe] of TOC) {
    const key = norm(probe);
    const tocIdx = texts.findIndex((t) => t.includes('СОДЕРЖАНИЕ'));
    for (let i = tocIdx + 1; i < n; i++) { // ищем после страницы содержания
      const t = texts[i];
      if (t.includes(key)) { pages[title] = i + 1; break; }
    }
    if (!pages[title]) throw new Error('Не найден раздел в PDF: ' + probe);
  }
  return { pages, n };
}
